import { test, expect } from '@playwright/test';
import {
    setupInterviewPage,
    waitForInterviewReady,
    mockRateLimit,
    mockNetworkFailureWithRetry
} from '../../test-utils/playwright-helpers';
import { TEST_IDS } from '../../test-utils/test-ids';

test.describe('Error Recovery & Resilience', () => {
    // Note: We do NOT use beforeEach for setupInterviewPage because
    // each test needs precise control over WHEN navigation happens
    // relative to mock setup.

    // Global console capture for debugging
    test.beforeEach(async ({ page }) => {
        page.on('console', msg => console.log(`PAGE LOG: ${msg.text()}`));
        page.on('pageerror', err => console.log(`PAGE ERROR: ${err.message}`));
    });

    test('VAD Initialization Failure (Fallback to Manual)', async ({ page }) => {
        // 1. Initial Setup
        await page.context().grantPermissions(['microphone']);

        // 2. Add Init Script (Runs on every load)
        await page.addInitScript(() => {
            console.log('PAGE LOG: Init script running');
            (window as any).__PLAYWRIGHT_TEST__ = true;

            // Mock VAD
            (window as any).mockMicVAD = {
                new: async (options: any) => ({
                    start: async () => { },
                    pause: async () => { },
                    destroy: async () => { },
                }),
            };

            // Mock generic success for Chat API to avoid "Processing" state hang
            (window as any).__MOCK_CHAT_RESPONSE__ = 'Test Response';

            // Mock generic successful audio setup if not already mocked
            if (!navigator.mediaDevices) {
                (navigator as any).mediaDevices = {};
            }

            // Mock getUserMedia to return a fake stream
            if (!navigator.mediaDevices.getUserMedia) {
                navigator.mediaDevices.getUserMedia = async () => {
                    const ctx = new AudioContext();
                    return ctx.createMediaStreamDestination().stream;
                };
            }

            // Enable VAD feature flag
            localStorage.setItem('algomind_feature_flags', JSON.stringify({
                ENABLE_VAD_INTERRUPTIONS: true
            }));

            // Force VAD Failure hook
            (window as any).__FORCE_VAD_FAILURE__ = true;
            console.log('PAGE LOG: Flags set in init script');
        });

        // Mock API route for Intro
        await page.route(/.*\/api\/chat.*/, async (route) => {
            await route.fulfill({
                status: 200,
                contentType: 'application/json',
                body: JSON.stringify({ response: 'Intro done' })
            });
        });

        // 3. Navigate
        await page.goto('/interview');
        await page.waitForLoadState('networkidle');

        // 4. Wait for Begin button
        const beginBtn = page.getByRole('button', { name: /begin interview/i });
        await expect(beginBtn).toBeVisible({ timeout: 10000 });
        await beginBtn.click();

        // 5. Verify fallback UI appeared
        await expect(page.getByTestId(TEST_IDS.VAD_ERROR_BANNER)).toBeVisible({ timeout: 10000 });

        // 6. Verify mic button still available
        await expect(page.getByTestId(TEST_IDS.MIC_BUTTON).first()).toBeEnabled({ timeout: 5000 });
    });

    test('Groq Rate Limit (Fallback Handling)', async ({ page }) => {
        // 1. Mock Intro API first
        await page.route(/.*\/api\/chat.*/, async (route) => {
            await route.fulfill({
                status: 200,
                contentType: 'application/json',
                body: JSON.stringify({ response: 'Intro done' })
            });
        });

        // 2. Navigate & Setup
        await setupInterviewPage(page);
        await waitForInterviewReady(page);

        // 3. Set up rate limit mock (Overrides previous route)
        const { getCallCount } = await mockRateLimit(page);

        // 4. Trigger an AI interaction via our test hook
        await page.evaluate(() => {
            console.log('Test: Triggering AI call via hook');
            if ((window as any).__TRIGGER_AI_CALL__) {
                (window as any).__TRIGGER_AI_CALL__('explain binary search');
            } else {
                throw new Error('Test hook __TRIGGER_AI_CALL__ not found');
            }
        });

        // 5. Verify fallback/retry happened gracefully
        // We expect the success message from the mock after the rate limit was handled
        await expect(page.getByText(/success after retry/i)).toBeVisible({ timeout: 20000 });

        // 6. Confirm rate limit was actually triggered at least once
        expect(getCallCount()).toBeGreaterThan(0);
    });

    test('Network Failure (Retry Logic)', async ({ page }) => {
        // 1. Navigate & Setup
        await setupInterviewPage(page);
        await waitForInterviewReady(page);

        // 2. Set up network failure mock AFTER page is loaded
        const { getCallCount } = await mockNetworkFailureWithRetry(page, 1);

        // 3. Trigger AI call via hook
        await page.evaluate(() => {
            console.log('Test: Triggering AI call via hook (Network Failure)');
            if ((window as any).__TRIGGER_AI_CALL__) {
                (window as any).__TRIGGER_AI_CALL__('hello network test');
            } else {
                throw new Error('Test hook __TRIGGER_AI_CALL__ not found');
            }
        });

        // 4. Verify eventual success
        await expect(page.getByText(/success after retry/i)).toBeVisible({ timeout: 20000 });

        // 5. Verify retry happened (call count should be > 1)
        expect(getCallCount()).toBeGreaterThan(1);
    });
});

import { test, expect } from '@playwright/test';
import {
    setupInterviewPage,
    waitForInterviewReady,
    InterviewPanelPOM,
    mockChatAPI
} from '../../test-utils/playwright-helpers';
import { TEST_IDS } from '../../test-utils/test-ids';

test.describe('Feature Flags Integration', () => {

    test('All flags OFF (Manual Mode)', async ({ page }) => {
        // Disable all flags before navigation
        await page.addInitScript(() => {
            localStorage.setItem('feature_ENABLE_VAD_INTERRUPTIONS', 'false');
            localStorage.setItem('feature_ENABLE_SMART_ROUTING', 'false');
            localStorage.setItem('feature_ENABLE_CHUNKED_RESPONSES', 'false');
        });

        // Setup
        await setupInterviewPage(page, '/interview');
        await mockChatAPI(page, 'Hello! Ready for manual mode interview.');
        await waitForInterviewReady(page);

        // Use POM to avoid strict mode
        const interview = new InterviewPanelPOM(page);

        // Verify mic button is visible (manual mode)
        await expect(interview.micButton()).toBeVisible({ timeout: 5000 });

        // Verify status shows manual mode (waiting for click)
        const status = await interview.getMicStatus();
        console.log('Manual mode status:', status);
        expect(status.toLowerCase()).toMatch(/waiting|click|start|ready/i);

        console.log('Ô£à All flags OFF test passed');
    });

    test('VAD Only triggers auto-start', async ({ page }) => {
        // Enable VAD flag before navigation
        await page.addInitScript(() => {
            localStorage.setItem('feature_ENABLE_VAD_INTERRUPTIONS', 'true');
            localStorage.setItem('feature_ENABLE_SMART_ROUTING', 'false');
            localStorage.setItem('feature_ENABLE_CHUNKED_RESPONSES', 'false');
        });

        // Setup
        await setupInterviewPage(page, '/interview');
        await mockChatAPI(page, 'Hello! VAD mode active.');
        await waitForInterviewReady(page);

        // Use POM
        const interview = new InterviewPanelPOM(page);

        // Check initial status
        const statusIndicator = interview.micStatusText();
        await expect(statusIndicator).toBeVisible({ timeout: 5000 });

        const status = await interview.getMicStatus();
        console.log('VAD mode status:', status);

        // In VAD mode, might auto-start OR wait for manual
        // Both are valid depending on browser permissions
        if (status.toLowerCase().includes('listen') || status.toLowerCase().includes('auto-submit')) {
            console.log('Ô£à VAD auto-started (listening)');
        } else if (status.toLowerCase().match(/waiting|click/)) {
            console.log('VAD waiting for manual start (expected in headless)');

            // Try manual click to trigger VAD
            await interview.clickMic();
            await page.waitForTimeout(1500);

            const updatedStatus = await interview.getMicStatus();
            console.log('After click:', updatedStatus);

            // After manual trigger, should be listening OR still waiting (both OK)
            expect(updatedStatus.toLowerCase()).toMatch(/listen|waiting|ready|auto-submit/i);
        }

        console.log('Ô£à VAD flag test passed');
    });
});

import { test, expect } from '@playwright/test';
import {
    setupInterviewPage,
    waitForInterviewReady,
    InterviewPanelPOM,
    mockChatAPI,
    debugInterviewState,
    dismissOnboardingModal
} from '../../test-utils/playwright-helpers';

test.describe('Voice Interview Integration', () => {
    test.use({ viewport: { width: 1920, height: 1080 } });

    test.beforeEach(async ({ page }) => {
        // Navigate to interview page
        await setupInterviewPage(page, '/interview');

        // Dismiss onboarding if present
        await dismissOnboardingModal(page);

        // Wait for "Begin Interview Experience" or similar readiness signal
        // Note: waitForInterviewReady does this, but we want to be explicit in beforeEach if needed.
        // For now, we'll rely on the test logic calling waitForInterviewReady or similar.
        // However, the user request specifically asked to:
        // "Waits for the 'Begin Interview Experience' button to be visible before proceeding."
        const beginBtn = page.getByRole('button', { name: /begin interview/i });
        try {
            await beginBtn.waitFor({ state: 'visible', timeout: 10000 });
        } catch (e) {
            console.log('Begin Interview button not found in beforeEach (might be already clicked or different flow)');
        }
    });

    test('Complete interview flow (End-to-End)', async ({ page }) => {
        // Increase timeout for this test
        test.setTimeout(60000);

        console.log('\n=== STEP 0: Dismiss Onboarding (Double Check) ===');
        await dismissOnboardingModal(page);

        // Note: setupInterviewPage is already called in beforeEach, but the test structure
        // in the user's snippet implies it was called inside the test. 
        // The user asked to ADD a beforeEach. 
        // We should PROBABLY remove the direct call to setupInterviewPage inside the test 
        // to avoid double navigation, OR just let it be (it navigates again).
        // Let's remove the explicit setupInterviewPage call here since it's in beforeEach now.
        // But wait, setupInterviewPage also MOCKS things. We need to make sure mocks persist.
        // Playwright page mocks usually persist until closed.
        // To be safe and follow instructions "Add a beforeEach hook... that Navigates...", 
        // and "In voice-interview.test.tsx, call dismissOnboardingModal(page) at the very start of every test block",
        // I will keep the mocks but remove the navigation if it's redundant, or just re-run it.
        // Actually, the user instruction 2 says: "call dismissOnboardingModal(page) at the very start of every test block, immediately after page navigation".
        // This suggests the test might still be doing navigation.
        // Let's stick to the prompt:
        // 3. Add beforeEach...
        // 2. Call dismissOnboardingModal at start of test...

        console.log('\n=== STEP 1: Setup Interview Page (Already done in beforeEach) ===');
        // We'll re-run setup to ensure fresh state if the test assumes it, or just rely on beforeEach.
        // Given the instructions, I'll trust beforeEach does the nav.

        console.log('\n=== STEP 2: Install Chat API Mock ===');
        // Mock BEFORE waiting for ready to catch initial intro call
        await mockChatAPI(page, 'Hello! I understand you want to start the interview.');

        console.log('\n=== STEP 3: Wait for Interview Ready ===');
        await waitForInterviewReady(page);

        console.log('\n=== STEP 4: Initialize POM ===');
        const interview = new InterviewPanelPOM(page);

        console.log('\n=== STEP 5: Wait for Interview to be in Ready State ===');
        // This handles "THINKING..." and "AI IS SPEAKING..." states
        await interview.waitForReady(30000);

        console.log('\n=== STEP 6: Verify Mic Status Indicator Visible ===');
        await expect(interview.micStatusText()).toBeVisible({ timeout: 5000 });

        console.log('\n=== STEP 7: Get Initial Mic Status ===');
        const initialStatus = await interview.getMicStatus();
        console.log('Initial mic status:', initialStatus);

        // Verify initial status is reasonable
        expect(initialStatus.toLowerCase()).toMatch(/waiting|click|start|ready|auto-submit|mic/i);

        console.log('\n=== STEP 8: Wait for Mic Button to be Enabled ===');
        await interview.waitForMicEnabled(10000);

        console.log('\n=== STEP 9: Click Mic Button (with retry) ===');
        await interview.clickMicSafely(3);

        console.log('\n=== STEP 10: Verify Mic State After Click ===');
        // Wait a bit for state to update
        await page.waitForTimeout(1500);

        const activeStatus = await interview.getMicStatus();
        console.log('Active mic status:', activeStatus);

        // After clicking, status should indicate listening or waiting (both valid)
        expect(activeStatus.toLowerCase()).toMatch(/listen|waiting|ready|click|auto-submit|mic/i);

        console.log('\n=== STEP 11: Verify Conversation View Visible ===');
        await expect(interview.conversationView()).toBeVisible({ timeout: 5000 });

        console.log('\nÔ£à Voice interview flow test completed successfully\n');
    });
});

'use client';

import React, { useState, useEffect, useCallback, useRef } from 'react';
import {
    getVoiceConfig,
    setVoiceConfig,
    resetVoiceConfig,
    VOICE_CONFIG_DEFAULTS,
    type VoiceConfigValues,
} from '@/config/voice-config';
import type { InterruptionEventData } from '@/lib/voice/types';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function formatTs(ts: number): string {
    return new Date(ts).toLocaleTimeString([], {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
    });
}

const EVENT_COLORS: Record<string, string> = {
    interruption: 'text-red-400',
    resumption: 'text-green-400',
    debounce: 'text-orange-400',
    state_change: 'text-slate-500',
    confidence_reject: 'text-yellow-500',
    duration_reject: 'text-amber-500',
    manual_stop: 'text-red-300',
    manual_continue: 'text-blue-300',
    diagnostic: 'text-slate-600',
};

// ---------------------------------------------------------------------------
// Config slider component
// ---------------------------------------------------------------------------

function ConfigSlider({
    label,
    configKey,
    min,
    max,
    step,
    unit,
    config,
    onChange,
}: {
    label: string;
    configKey: keyof VoiceConfigValues;
    min: number;
    max: number;
    step: number;
    unit: string;
    config: VoiceConfigValues;
    onChange: (key: keyof VoiceConfigValues, value: number) => void;
}) {
    const value = config[configKey] as number;
    const defaultVal = VOICE_CONFIG_DEFAULTS[configKey] as number;
    const isModified = value !== defaultVal;

    return (
        <div className="space-y-1">
            <div className="flex items-center justify-between text-xs">
                <span className="text-slate-300 font-medium">{label}</span>
                <span className={isModified ? 'text-blue-400 font-bold' : 'text-slate-500'}>
                    {value}{unit}
                    {isModified && (
                        <span className="text-slate-600 ml-1">(default: {defaultVal})</span>
                    )}
                </span>
            </div>
            <input
                type="range"
                min={min}
                max={max}
                step={step}
                value={value}
                onChange={(e) => onChange(configKey, Number(e.target.value))}
                className="w-full h-1.5 bg-slate-800 rounded-full appearance-none cursor-pointer accent-blue-500"
            />
        </div>
    );
}

// ---------------------------------------------------------------------------
// Page
// ---------------------------------------------------------------------------

export default function VoiceDebugPage() {
    const [config, setLocalConfig] = useState<VoiceConfigValues>(VOICE_CONFIG_DEFAULTS);
    const [eventStream, setEventStream] = useState<InterruptionEventData[]>([]);
    const streamRef = useRef<HTMLDivElement>(null);

    // Load config from localStorage on mount
    useEffect(() => {
        setLocalConfig(getVoiceConfig());
    }, []);

    // Poll for event stream updates (from the InterruptionManager singleton)
    useEffect(() => {
        let timer: ReturnType<typeof setInterval>;

        async function pollEvents() {
            try {
                const { InterruptionManager } = await import('@/lib/voice/interruption-manager');
                // We can't access the singleton from here since it's in ConversationView
                // Instead, read from a global debug hook if available
                 
                const w = window as unknown as { __algomind_im_debug?: InstanceType<typeof InterruptionManager> };
                if (w.__algomind_im_debug) {
                    const im = w.__algomind_im_debug;
                    setEventStream([...im.getEventStream()]);
                }
            } catch {
                // InterruptionManager not available
            }
        }

        timer = setInterval(pollEvents, 500);
        return () => clearInterval(timer);
    }, []);

    // Auto-scroll event stream
    useEffect(() => {
        if (streamRef.current) {
            streamRef.current.scrollTop = streamRef.current.scrollHeight;
        }
    }, [eventStream]);

    const handleConfigChange = useCallback((key: keyof VoiceConfigValues, value: number | boolean) => {
        const updated = setVoiceConfig({ [key]: value });
        setLocalConfig(updated);

        // Also hot-update any live InterruptionManager instance
         
        const w = window as unknown as { __algomind_im_debug?: { setConfig: (c: Partial<VoiceConfigValues>) => void } };
        if (w.__algomind_im_debug?.setConfig) {
            w.__algomind_im_debug.setConfig({ [key]: value });
        }
    }, []);

    const handleReset = useCallback(() => {
        const defaults = resetVoiceConfig();
        setLocalConfig(defaults);
         
        const w = window as unknown as { __algomind_im_debug?: { setConfig: (c: Partial<VoiceConfigValues>) => void } };
        if (w.__algomind_im_debug?.setConfig) {
            w.__algomind_im_debug.setConfig(defaults);
        }
    }, []);

    // Compute stats from event stream
    const stats = React.useMemo(() => {
        const interruptions = eventStream.filter(e => e.event === 'interruption');
        const confidenceRejects = eventStream.filter(e => e.event === 'confidence_reject');
        const durationRejects = eventStream.filter(e => e.event === 'duration_reject');
        const manualStops = eventStream.filter(e => e.event === 'manual_stop');
        const avgConfidence = interruptions.length > 0
            ? interruptions.reduce((sum, e) => sum + (e.confidence ?? 0), 0) / interruptions.length
            : 0;

        return {
            total: eventStream.length,
            interruptions: interruptions.length,
            confidenceRejects: confidenceRejects.length,
            durationRejects: durationRejects.length,
            manualStops: manualStops.length,
            avgConfidence,
            rejectRate: eventStream.length > 0
                ? ((confidenceRejects.length + durationRejects.length) / eventStream.length * 100)
                : 0,
        };
    }, [eventStream]);

    return (
        <div className="min-h-screen bg-slate-950 text-white p-6 lg:p-10">
            <div className="max-w-4xl mx-auto space-y-8">
                {/* Header */}
                <div className="space-y-1">
                    <h1 className="text-2xl font-bold tracking-tight">Voice Debug Panel</h1>
                    <p className="text-sm text-slate-400">
                        Tune interruption parameters and monitor VAD events in real-time.
                    </p>
                </div>

                {/* Stats bar */}
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                    {[
                        { label: 'Interruptions', value: stats.interruptions, color: 'text-red-400' },
                        { label: 'Rejected (conf)', value: stats.confidenceRejects, color: 'text-yellow-400' },
                        { label: 'Rejected (dur)', value: stats.durationRejects, color: 'text-amber-400' },
                        { label: 'Reject Rate', value: `${stats.rejectRate.toFixed(1)}%`, color: 'text-orange-400' },
                    ].map(s => (
                        <div key={s.label} className="p-3 rounded-xl bg-slate-900/40 border border-slate-800/50">
                            <div className="text-[10px] font-bold uppercase tracking-wider text-slate-500">{s.label}</div>
                            <div className={`text-xl font-bold ${s.color}`}>{s.value}</div>
                        </div>
                    ))}
                </div>

                {/* Config tuning */}
                <div className="p-5 rounded-2xl bg-slate-900/40 border border-slate-800/50 space-y-5">
                    <div className="flex items-center justify-between">
                        <h2 className="text-sm font-bold uppercase tracking-wider text-slate-300">
                            Configuration
                        </h2>
                        <button
                            onClick={handleReset}
                            className="text-[10px] font-bold uppercase tracking-widest text-red-400 hover:text-red-300 transition-colors"
                        >
                            Reset Defaults
                        </button>
                    </div>

                    <div className="grid gap-4 sm:grid-cols-2">
                        <ConfigSlider label="Grace Period" configKey="graceMs" min={100} max={2000} step={50} unit="ms" config={config} onChange={handleConfigChange} />
                        <ConfigSlider label="Debounce Cooldown" configKey="debounceMs" min={200} max={3000} step={100} unit="ms" config={config} onChange={handleConfigChange} />
                        <ConfigSlider label="Speech End Confirm" configKey="speechEndConfirmMs" min={200} max={3000} step={100} unit="ms" config={config} onChange={handleConfigChange} />
                        <ConfigSlider label="Min Confidence" configKey="minConfidence" min={0.3} max={1.0} step={0.05} unit="" config={config} onChange={handleConfigChange} />
                        <ConfigSlider label="Min Speech Duration" configKey="minSpeechDurationMs" min={50} max={1000} step={25} unit="ms" config={config} onChange={handleConfigChange} />
                        <ConfigSlider label="Consecutive Frames" configKey="consecutiveHighFrames" min={1} max={10} step={1} unit="" config={config} onChange={handleConfigChange} />
                    </div>

                    {/* Debug mode toggle */}
                    <div className="flex items-center justify-between pt-3 border-t border-slate-800/50">
                        <div>
                            <span className="text-xs font-bold text-slate-300">Debug Mode</span>
                            <p className="text-[10px] text-slate-500">Verbose console logging for all decisions</p>
                        </div>
                        <button
                            role="switch"
                            aria-checked={config.debugMode}
                            onClick={() => handleConfigChange('debugMode', !config.debugMode)}
                            className={`relative inline-flex h-7 w-12 shrink-0 cursor-pointer rounded-full border-2 transition-colors duration-200 ${config.debugMode
                                ? 'bg-blue-600 border-blue-500'
                                : 'bg-slate-700 border-slate-600'
                                }`}
                        >
                            <span
                                className={`pointer-events-none inline-block h-5 w-5 transform rounded-full bg-white shadow-lg transition-transform duration-200 mt-[1px] ${config.debugMode ? 'translate-x-[22px]' : 'translate-x-[2px]'
                                    }`}
                            />
                        </button>
                    </div>
                </div>

                {/* Event stream */}
                <div className="space-y-2">
                    <div className="flex items-center justify-between">
                        <h2 className="text-sm font-bold uppercase tracking-wider text-slate-300">
                            Event Stream
                        </h2>
                        <span className="text-[10px] text-slate-500">
                            {eventStream.length} events
                            {eventStream.length === 0 && ' ÔÇö start an interview with VAD enabled to see events'}
                        </span>
                    </div>
                    <div
                        ref={streamRef}
                        className="h-64 overflow-y-auto rounded-xl bg-slate-900/60 border border-slate-800/50 p-3 font-mono text-[11px] space-y-0.5 scrollbar-thin scrollbar-thumb-slate-700"
                    >
                        {eventStream.length === 0 ? (
                            <div className="text-slate-600 text-center py-8">
                                No events yet. Expose the InterruptionManager instance to <code>window.__algomind_im_debug</code> during an interview to enable live monitoring.
                            </div>
                        ) : (
                            eventStream.map((evt, i) => (
                                <div key={i} className="flex gap-2 items-start">
                                    <span className="text-slate-600 shrink-0">{formatTs(evt.timestamp)}</span>
                                    <span className={`font-bold shrink-0 ${EVENT_COLORS[evt.event] ?? 'text-slate-400'}`}>
                                        {evt.event}
                                    </span>
                                    {evt.decision && (
                                        <span className="text-slate-500">ÔåÆ {evt.decision}</span>
                                    )}
                                    {evt.confidence !== undefined && (
                                        <span className="text-blue-400/60">conf={evt.confidence.toFixed(3)}</span>
                                    )}
                                    {evt.speechDurationMs !== undefined && (
                                        <span className="text-purple-400/60">{evt.speechDurationMs}ms</span>
                                    )}
                                    {evt.reason && (
                                        <span className="text-slate-600 truncate">{evt.reason}</span>
                                    )}
                                </div>
                            ))
                        )}
                    </div>
                </div>

                {/* Current config dump */}
                <details className="text-xs text-slate-500">
                    <summary className="cursor-pointer hover:text-slate-300 font-bold uppercase tracking-widest transition-colors">
                        Debug: Raw Config
                    </summary>
                    <pre className="mt-2 p-3 rounded-lg bg-slate-900/60 border border-slate-800/50 overflow-auto font-mono text-[10px]">
                        {JSON.stringify(config, null, 2)}
                    </pre>
                </details>
            </div>
        </div>
    );
}

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { POST } from '../chat/route';
import { createServerSupabase } from '@/lib/supabase/server';
import { getAIClient } from '@/lib/ai/client';
import { supabaseHybridSearch } from '@/lib/rag/supabaseVectorStore';

// Mock dependencies
vi.mock('@/lib/supabase/server', () => ({
    createServerSupabase: vi.fn()
}));

vi.mock('@/lib/ai/client', () => ({
    getAIClient: vi.fn()
}));

vi.mock('@/lib/rag/supabaseVectorStore', () => ({
    supabaseHybridSearch: vi.fn()
}));

// Mock rate limiter
vi.mock('@/lib/rate-limit/user-rate-limiter', () => ({
    incrementUserUsage: vi.fn().mockResolvedValue(true)
}));

describe('/api/chat', () => {
    // Setup common mocks
    const mockGenerateResponse = vi.fn();
