});

import { NextRequest, NextResponse } from 'next/server';
import { createServerSupabase } from '@/lib/supabase/server';
import { fetchAndSaveLeetCodeProfile } from '@/lib/leetcode/client';
import { getRedis } from '@/lib/upstash/client';

export async function POST(req: NextRequest) {
    try {
        const supabase = await createServerSupabase();
        const { data: { user } } = await supabase.auth.getUser();

        if (!user) {
            return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
        }

        const redis = getRedis();
        const limitKey = `lc_refresh:${user.id}`;

        // Check rate limit: 1 hour cooldown for manual refresh
        if (redis) {
            const isLimited = await redis.get(limitKey);
            if (isLimited) {
                return NextResponse.json({ error: 'Can refresh once per hour' }, { status: 429 });
            }
        }

        // Get username from prefs
        const { data: prefs } = await supabase
            .from('user_preferences')
            .select('leetcode_username')
            .eq('user_id', user.id)
            .single();

        if (!prefs || !prefs.leetcode_username) {
            return NextResponse.json({ error: 'No LeetCode profile connected' }, { status: 400 });
        }

        // Set rate limit (3600s = 1 hour)
        if (redis) {
            await redis.set(limitKey, 'limited', { ex: 3600 });
        }

        // Trigger manual refresh
        void fetchAndSaveLeetCodeProfile(user.id, prefs.leetcode_username);

        return NextResponse.json({ triggered: true });
    } catch (error) {
        console.error('[LeetCode Refresh] Exception:', error);
        return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from 'next/server';
import { createServerSupabase } from '@/lib/supabase/server';

export async function GET(req: NextRequest) {
    try {
        const supabase = await createServerSupabase();
        const { data: { user } } = await supabase.auth.getUser();

        if (!user) {
            return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
        }

        // 1. Query leetcode_profiles and user_preferences
        const { data: profile } = await supabase
            .from('leetcode_profiles')
            .select('*')
            .eq('user_id', user.id)
            .single();

        const { data: prefs } = await supabase
            .from('user_preferences')
            .select('leetcode_fetch_status, leetcode_username')
            .eq('user_id', user.id)
            .single();

        // 2. If no row
        if (!profile && (!prefs || prefs.leetcode_fetch_status !== 'pending')) {
            return NextResponse.json({ connected: false });
        }

        // 3. Return mapped profile
        return NextResponse.json({
            connected: true,
            username: profile?.username || prefs?.leetcode_username,
            totalSolved: profile?.total_solved || 0,
            easySolved: profile?.easy_solved || 0,
            mediumSolved: profile?.medium_solved || 0,
            hardSolved: profile?.hard_solved || 0,
            ranking: profile?.ranking || null,
            contestRating: profile?.contest_rating || null,
            fetchStatus: prefs?.leetcode_fetch_status || 'success',
            lastFetchedAt: profile?.fetched_at || null
        });
    } catch (error) {
        console.error('[LeetCode Status] Exception:', error);
        return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
    }
}

'use client';

import React, { useEffect } from 'react';
import { useVoiceInput } from '@/hooks/useVoiceInput';
import { MicrophoneButton } from '@/components/voice/MicrophoneButton';
import { TranscriptViewer } from '@/components/voice/TranscriptViewer';
import { Card } from '@/components/ui/card';

export default function VoiceTestPage() {
    const {
        isListening,
        transcript,
        interimTranscript,
        startListening,
        stopListening,
        resetTranscript,
        isSupported,
        error
    } = useVoiceInput();

    // Handle keyboard shortcut (Space to toggle)
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.code === 'Space' && e.target === document.body) {
                e.preventDefault(); // Prevent scrolling
                if (isListening) {
                    stopListening();
                } else {
                    startListening();
                }
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isListening, startListening, stopListening]);

    return (
        <div className="container mx-auto p-8 max-w-4xl space-y-8">
            <div className="text-center space-y-2">
                <h1 className="text-3xl font-bold tracking-tight">Voice Input Pipeline Test</h1>
                <p className="text-muted-foreground">Phase 3.1 Verification</p>
            </div>

            {!isSupported && (
                <div className="bg-destructive/10 text-destructive p-4 rounded-md border border-destructive/20 text-center">
                    Web Speech API is not supported in this browser. Please use Chrome or Edge.
                </div>
            )}

            {error && (
                <div className="bg-destructive/10 text-destructive p-4 rounded-md border border-destructive/20 text-center">
                    {error}
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-[1fr_2fr] gap-8 items-start">
                {/* Controls */}
                <div className="flex flex-col items-center justify-center space-y-8 py-8 bg-card rounded-xl border shadow-sm">
                    <MicrophoneButton
                        isListening={isListening}
                        onClick={isListening ? stopListening : startListening}
                        error={error}
                        disabled={!isSupported}
                    />

                    <div className="text-sm text-center text-muted-foreground px-4">
                        <p>Try saying DSA terms:</p>
                        <ul className="mt-2 space-y-1 font-mono text-xs">
                            <li>&quot;binary search tree&quot;</li>
                            <li>&quot;dynamic programming&quot;</li>
                            <li>&quot;O(n squared)&quot;</li>
                        </ul>
                    </div>

                    <button
                        onClick={resetTranscript}
                        className="text-xs text-red-500 hover:underline"
                    >
                        Clear Transcript
                    </button>
                </div>

                {/* Transcript View */}
                <div className="h-[400px]">
                    <TranscriptViewer
                        transcript={transcript}
                        interimTranscript={interimTranscript}
                    />
                </div>
            </div>
        </div>
    );
}

