                            <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                        ) : (
                            <FileDown className="w-4 h-4 mr-2" />
                        )}
                        {showLoading ? 'Generating...' : 'Export Report'}
                    </Button>
                );
            }}
        </PDFDownloadLink>
    );
}

