'use client';

import React from 'react';
import {
    LineChart,
    Line,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip,
    ResponsiveContainer,
    ReferenceLine,
    Area,
    AreaChart
} from 'recharts';
import { SessionHistory, CognitiveSkill } from '@/types/assessment';
import { SKILL_DEFINITIONS } from '@/lib/assessment/skill-registry';
import { TrendingUp, TrendingDown, Minus } from 'lucide-react';
import { cn } from '@/lib/utils';

interface SkillTrendCardProps {
    skill: CognitiveSkill;
    sessions: SessionHistory[];
    className?: string;
}

function SkillTrendCardBase({ skill, sessions, className }: SkillTrendCardProps) {
    const definition = SKILL_DEFINITIONS[skill];

    // Prep data - most recent last
    const chartData = sessions.slice().reverse().map((session, index) => ({
        session: index + 1,
        score: session.skills[skill] || 0,
        timestamp: session.timestamp,
    }));

    // Calculate trend
    const current = chartData[chartData.length - 1]?.score || 0;
    const previous = chartData[chartData.length - 2]?.score || current;
    const diff = current - previous;

    const trend =
        diff > 0.5 ? 'improving' :
            diff < -0.5 ? 'declining' :
                'stable';

    return (
        <div className={cn("flex flex-col gap-4 p-5 bg-slate-900/40 border border-slate-800/60 rounded-3xl h-full shadow-lg", className)}>
            <div className="flex justify-between items-start">
                <div className="space-y-1">
                    <h4 className="text-xs font-black uppercase tracking-widest text-slate-500">{definition.name}</h4>
                    <div className="flex items-center gap-2">
                        <span className="text-2xl font-black text-white">{current.toFixed(1)}</span>
                        <div className={cn(
                            "flex items-center gap-1 text-[10px] font-black px-1.5 py-0.5 rounded-full uppercase tracking-tighter",
                            trend === 'improving' ? "bg-emerald-500/10 text-emerald-400" :
                                trend === 'declining' ? "bg-red-500/10 text-red-400" :
                                    "bg-slate-500/10 text-slate-500"
                        )}>
                            {trend === 'improving' && <TrendingUp className="w-3 h-3" />}
                            {trend === 'declining' && <TrendingDown className="w-3 h-3" />}
                            {trend === 'stable' && <Minus className="w-3 h-3" />}
                            {trend}
                        </div>
                    </div>
                </div>
                <div
                    className="w-10 h-10 rounded-2xl flex items-center justify-center opacity-80 shadow-lg"
                    style={{ backgroundColor: `${definition.color}20`, border: `1px solid ${definition.color}40` }}
                >
                    <div className="w-3 h-3 rounded-full" style={{ backgroundColor: definition.color }} />
                </div>
            </div>

            <div className="h-28 w-full mt-2">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={chartData}>
                        <defs>
                            <linearGradient id={`gradient-${skill}`} x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor={definition.color} stopOpacity={0.3} />
                                <stop offset="95%" stopColor={definition.color} stopOpacity={0} />
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1e293b" opacity={0.5} />
                        <XAxis
                            dataKey="session"
                            hide
                        />
                        <YAxis
                            domain={[0, 10]}
                            hide
                        />
                        <Tooltip
                            contentStyle={{
                                backgroundColor: '#0f172a',
                                border: '1px solid #1e293b',
                                borderRadius: '8px',
                                fontSize: '10px',
                                color: '#f8fafc',
                                padding: '4px 8px'
                            }}
                            labelStyle={{ display: 'none' }}
                        />
                        <ReferenceLine y={5} stroke="#334155" strokeDasharray="3 3" />
                        <Area
                            type="monotone"
                            dataKey="score"
                            stroke={definition.color}
                            strokeWidth={3}
                            fillOpacity={1}
                            fill={`url(#gradient-${skill})`}
                            isAnimationActive={true}
                            animationDuration={1500}
                        />
                    </AreaChart>
                </ResponsiveContainer>
            </div>
        </div>
    );
}

export const SkillTrendCard = React.memo(SkillTrendCardBase);

'use client';

import React from 'react';
import { UserProgress } from '@/types/assessment';
import { TrendingUp, TrendingDown, Target, Clock, Code2, Sparkles } from 'lucide-react';
import { SKILL_DEFINITIONS } from '@/lib/assessment/skill-registry';
import { CognitiveSkill } from '@/types/assessment';

interface StatsOverviewProps {
    progress: UserProgress | null;
}

export function StatsOverview({ progress }: StatsOverviewProps) {
    if (!progress) return null;

    const totalMinutes = Math.floor((progress.sessions.reduce((acc: number, s: any) => acc + (s.duration || 0), 0)) / 60);
    const problemsSolved = progress.totalSessions;
    const avgScore = progress.averageScore;

    // Calculate improvement (comparing last 2 sessions if available)
    const currentAvg = progress.sessions[0]?.overallScore || 0;
    const prevAvg = progress.sessions[1]?.overallScore || currentAvg;
    const improvement = prevAvg === 0 ? 0 : ((currentAvg - prevAvg) / prevAvg) * 100;

    // Identify strengths and weaknesses
    const skillAverages = Object.keys(SKILL_DEFINITIONS).map(skillId => {
        const sId = skillId as CognitiveSkill;
        const total = progress.sessions.reduce((acc: number, s: any) => acc + (s.skills[sId] || 0), 0);
        return {
            id: sId,
            name: SKILL_DEFINITIONS[sId].name,
            avg: total / progress.totalSessions,
            color: SKILL_DEFINITIONS[sId].color
        };
    });

    const topSkills = [...skillAverages].sort((a, b) => b.avg - a.avg).slice(0, 3);
    const needsWork = [...skillAverages].sort((a, b) => a.avg - b.avg).slice(0, 3);

    return (
        <div className="space-y-6">
            <div className="grid grid-cols-2 gap-4" data-tour="performance-insights">
                <StatItem
                    icon={<Clock className="w-4 h-4 text-emerald-400" />}
                    label="Practice Time"
                    value={`${totalMinutes}m`}
                />
                <StatItem
                    icon={<Code2 className="w-4 h-4 text-blue-400" />}
                    label="Problems Solved"
                    value={problemsSolved.toString()}
                />
                <StatItem
                    icon={<Target className="w-4 h-4 text-purple-400" />}
                    label="Avg Score"
                    value={avgScore.toFixed(1)}
                />
                <StatItem
                    icon={improvement >= 0 ? <TrendingUp className="w-4 h-4 text-emerald-400" /> : <TrendingDown className="w-4 h-4 text-red-400" />}
                    label="Improvement"
                    value={`${improvement >= 0 ? '+' : ''}${improvement.toFixed(1)}%`}
                    color={improvement >= 0 ? 'text-emerald-400' : 'text-red-400'}
                />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-2" data-tour="cognitive-radar">
                <div className="space-y-3">
                    <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 mb-1 flex items-center gap-1.5">
                        <Sparkles className="w-3 h-3 text-amber-400" /> Top Strengths
                    </h4>
                    <div className="space-y-2">
                        {topSkills.map(skill => (
                            <SkillBar key={skill.id} name={skill.name} score={skill.avg} color={skill.color} />
                        ))}
                    </div>
                </div>

                <div className="space-y-3">
                    <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 mb-1 flex items-center gap-1.5">
                        <TrendingDown className="w-3 h-3 text-red-400" /> Areas for Growth
                    </h4>
                    <div className="space-y-2">
                        {needsWork.map(skill => (
                            <SkillBar key={skill.id} name={skill.name} score={skill.avg} color={skill.color} />
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
}

function StatItem({ icon, label, value, color = "text-white" }: { icon: React.ReactNode, label: string, value: string, color?: string }) {
    return (
        <div className="bg-slate-900/40 border border-slate-800/60 rounded-2xl p-3 flex flex-col gap-1 shadow-inner">
            <div className="flex items-center gap-2">
                {icon}
                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">{label}</span>
            </div>
            <span className={`text-xl font-black ${color}`}>{value}</span>
        </div>
    );
}

function SkillBar({ name, score, color }: { name: string, score: number, color: string }) {
    return (
        <div className="space-y-1.5">
            <div className="flex justify-between items-center px-0.5">
                <span className="text-[10px] font-bold text-slate-300 truncate mr-2">{name}</span>
                <span className="text-[10px] font-black text-slate-500">{score.toFixed(1)}</span>
            </div>
            <div className="h-1.5 w-full bg-slate-800/50 rounded-full overflow-hidden border border-slate-800/30">
                <div
                    className="h-full rounded-full transition-all duration-1000 ease-out"
                    style={{ width: `${(score / 10) * 100}%`, backgroundColor: color }}
                />
            </div>
        </div>
    );
}

