// Default fallback data in case DB fetch fails or table isn't populated yet
const DEFAULT_COMPANIES: CompanyProfile[] = [
    {
        id: 'general',
        name: 'General',
        emoji: '­ƒºá',
        theme_color: 'slate',
        persona_prompt: ''
    },
