                isDemo ? "h-[104px]" : "h-16"
            )} />
        </>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { isDemoMode, enableDemoMode, disableDemoMode } from '@/lib/demo/manager';
import { resetOnboarding, shouldShowOnboarding, markOnboardingComplete } from '@/lib/onboarding/manager';
import { useAuth } from '@/components/auth/AuthProvider';
import { getSupabase } from '@/lib/supabase/client';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { ArrowLeft, User, LogOut, Database, Shield, Play, FlaskConical, Mic } from 'lucide-react';
import Link from 'next/link';
import { toast } from 'sonner';

import { Switch } from '@/components/ui/switch';
import { setFeatureFlag, getFeatureFlag } from '@/lib/feature-flags';

import { VoiceSettings } from './VoiceSettings';
import { LeetCodeSettings } from './LeetCodeSettings';

export function SettingsPanel() {
    const [introEnabled, setIntroEnabled] = useState(false);
    const [demoMode, setDemoMode] = useState(false);
    const [mounted, setMounted] = useState(false);
    const [_isClearing, setIsClearing] = useState(false);
    const { user, signOut, isConfigured } = useAuth();
    const router = useRouter();
    const [vadEnabled, setVadEnabled] = useState(false);

    useEffect(() => {
        setMounted(true);
        setIntroEnabled(shouldShowOnboarding());
        setDemoMode(isDemoMode());
        setVadEnabled(getFeatureFlag('ENABLE_VAD_INTERRUPTIONS'));

        const handleDemoChange = (e: CustomEvent<{ enabled: boolean }>) => {
            setDemoMode(e.detail.enabled);
        };

        window.addEventListener('demo-mode-changed', handleDemoChange as EventListener);
        return () => {
            window.removeEventListener('demo-mode-changed', handleDemoChange as EventListener);
        };
    }, []);

    const _toggleIntro = () => {
        // ... (existing toggleIntro logic)
        if (introEnabled) {
            markOnboardingComplete();
            toast.success('Intro animation disabled for next visit');
        } else {
            resetOnboarding();
            toast.success('Intro animation enabled for next visit');
        }
        setIntroEnabled(!introEnabled);
    };

    const handleExitDemo = () => {
        disableDemoMode();
        window.dispatchEvent(new CustomEvent('demo-mode-changed', { detail: { enabled: false } }));
        toast.success('Demo mode disabled');
        router.refresh();
    };

    const handleVadToggle = (checked: boolean) => {
        setVadEnabled(checked);
        setFeatureFlag('ENABLE_VAD_INTERRUPTIONS', checked);
    };

    const handleStartDemoTour = () => {
        // Event listener in TourContext checks this
        if (!demoMode) {
            enableDemoMode();
            window.dispatchEvent(new CustomEvent('demo-mode-changed', { detail: { enabled: true } }));
        }
        window.dispatchEvent(new CustomEvent('start-tour'));
    };

    const _handleClearData = async () => {
        if (!confirm('Are you sure? This will delete ALL your interview sessions and progress. This cannot be undone!')) {
            return;
        }

        setIsClearing(true);

        try {
            // Clear localStorage
            localStorage.clear();
            // Force disable demo mode in state/UI too
            disableDemoMode();

            // If authenticated and Supabase is configured, clear database
            if (user && isConfigured) {
                const supabase = getSupabase();
                if (supabase) {
                    // Delete assessments first (foreign key constraint)
                    await supabase
                        .from('assessments')
                        .delete()
                        .eq('user_id', user.id);

                    // Delete sessions
                    await supabase
                        .from('interview_sessions')
                        .delete()
                        .eq('user_id', user.id);
                }
            }

            toast.success('All data cleared successfully!');
            router.refresh();
        } catch (error) {
            console.error('Failed to clear data:', error);
            toast.error('Failed to clear data. Please try again.');
        } finally {
            setIsClearing(false);
        }
    };

    const handleSignOut = async () => {
        disableDemoMode(); // Ensure demo mode is off on logout
        window.dispatchEvent(new CustomEvent('demo-mode-changed', { detail: { enabled: false } }));
        await signOut();
        toast.success('Signed out successfully');
        router.push('/');
    };

    if (!mounted) return null;

    return (
        <div className="space-y-6">
            {/* Back Link */}
            <Link href="/" className="inline-flex items-center text-slate-400 hover:text-white transition-colors">
                <ArrowLeft className="w-4 h-4 mr-2" />
                Back to Home
            </Link>

            <h1 className="text-3xl font-bold text-white">Settings</h1>

            {/* User Profile Card */}
            <Card className="bg-slate-900/50 border-slate-800">
                <CardHeader>
                    <CardTitle className="text-white flex items-center gap-2">
                        <User className="w-5 h-5" />
                        Profile
                    </CardTitle>
                    <CardDescription>Your account information</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                    {user ? (
                        <>
                            <div className="flex items-center gap-4 p-4 rounded-xl bg-slate-800/50 border border-slate-700">
                                {user.user_metadata?.avatar_url ? (
                                    <img
                                        src={user.user_metadata.avatar_url}
                                        alt={user.email || 'User'}
                                        className="w-16 h-16 rounded-full ring-2 ring-slate-600"
                                    />
                                ) : (
                                    <div className="w-16 h-16 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center text-white text-2xl font-bold">
                                        {user.email?.[0].toUpperCase()}
                                    </div>
                                )}
                                <div className="min-w-0 flex-1">
                                    <p className="text-lg font-semibold text-white truncate">
                                        {user.user_metadata?.full_name || 'AlgoMind User'}
                                    </p>
                                    <p className="text-slate-400 truncate">{user.email}</p>
                                </div>
                            </div>

                            <Button
                                onClick={handleSignOut}
                                variant="destructive"
                                className="w-full bg-red-600/10 hover:bg-red-600 text-red-500 hover:text-white border border-red-900/50 transition-all font-bold"
                            >
                                <LogOut className="w-4 h-4 mr-2" />
                                Sign Out
                            </Button>
                        </>
                    ) : (
                        <div className="p-4 rounded-xl bg-slate-800/50 border border-slate-700 text-center">
                            <p className="text-slate-400 mb-3">You're using AlgoMind as a guest</p>
                            <Button onClick={() => router.push('/login')}>
                                Sign In for Cloud Sync
                            </Button>
                        </div>
                    )}
                </CardContent>
            </Card>

            {/* Voice Settings */}
            <VoiceSettings />

            {/* VAD Settings */}
            <Card className="bg-slate-900/50 border-slate-800">
                <CardHeader>
                    <CardTitle className="text-white flex items-center gap-2">
                        <Mic className="w-5 h-5" />
                        Voice Activity Detection
                    </CardTitle>
                    <CardDescription>Automatically detects when you stop speaking. Disable if you experience mic issues.</CardDescription>
                </CardHeader>
                <CardContent>
                    <div className="flex items-center justify-between p-4 rounded-xl bg-slate-800/50 border border-slate-700">
                        <div className="space-y-0.5">
                            <label className="text-sm font-medium text-slate-300 block">Voice Activity Detection</label>
                            <p className="text-xs text-slate-500">Changes take effect on next interview session</p>
                        </div>
                        <Switch
                            checked={vadEnabled}
                            onCheckedChange={handleVadToggle}
                        />
                    </div>
                </CardContent>
            </Card>

            {/* Storage Info */}
            <Card className="bg-slate-900/50 border-slate-800">
                <CardHeader>
                    <CardTitle className="text-white flex items-center gap-2">
                        <Database className="w-5 h-5" />
                        Data Storage
                    </CardTitle>
                    <CardDescription>Where your data is stored</CardDescription>
                </CardHeader>
                <CardContent>
                    <div className="p-4 rounded-xl bg-slate-800/50 border border-slate-700">
                        <div className="flex items-center gap-2 mb-2">
                            <Shield className={`w-4 h-4 ${isConfigured ? 'text-emerald-400' : 'text-yellow-400'}`} />
                            <span className="font-medium text-white">
                                {isConfigured ? 'Cloud Storage (Supabase)' : 'Local Storage Only'}
                            </span>
                        </div>
                        <p className="text-sm text-slate-400">
                            {isConfigured
                                ? 'Your data is securely stored in the cloud and syncs across devices.'
                                : 'Data is stored locally in your browser. Sign in to enable cloud sync.'}
                        </p>
                    </div>
                </CardContent>
            </Card>

            {/* App Settings */}
            <Card className="bg-slate-900/50 border-slate-800">
                <CardHeader>
                    <CardTitle className="text-white">App Settings</CardTitle>
                    <CardDescription>Configure AlgoMind options</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                    {/* Combined Demo & Tour Control */}
                    <div className="flex items-center justify-between p-4 rounded-xl bg-slate-800/50 border border-slate-700" data-tour="intro-button">
                        <div className="flex items-center gap-3">
                            <div className="p-2 rounded-lg bg-blue-500/20">
                                {demoMode ? (
                                    <FlaskConical className="w-5 h-5 text-purple-400" />
                                ) : (
                                    <Play className="w-5 h-5 text-blue-400" />
                                )}
                            </div>
                            <div>
                                <h3 className="font-semibold text-white">
                                    {demoMode ? 'Demo Mode Active' : 'Interactive Demo'}
                                </h3>
                                <p className="text-sm text-slate-400">
                                    {demoMode
                                        ? 'Sample data loaded. Exit to clear.'
                                        : 'Experience AlgoMind with sample data and tour'}
                                </p>
                            </div>
                        </div>

                        {/* Dynamic Button: Start Tour OR Exit Demo */}
                        {demoMode ? (
                            <Button
                                onClick={handleExitDemo}
                                variant="destructive"
                                className="bg-red-500/10 text-red-400 hover:bg-red-500 hover:text-white border border-red-900/50"
                            >
                                Exit Demo Mode
                            </Button>
                        ) : (
                            <Button
                                onClick={handleStartDemoTour}
                                variant="default"
                                className="bg-blue-600 hover:bg-blue-500 text-white font-bold shadow-lg shadow-blue-500/20"
                            >
                                Start Demo Tour
                            </Button>
                        )}
                    </div>
                </CardContent>
            </Card>

            {/* LeetCode Integration */}
            <LeetCodeSettings />

            {/* App Info */}
            <Card className="bg-slate-900/50 border-slate-800">
                <CardHeader>
                    <CardTitle className="text-white">About AlgoMind</CardTitle>
                </CardHeader>
                <CardContent className="text-sm text-slate-400 space-y-2">
                    <p>Version: 1.0.0 (Beta)</p>
                    <p>Built with Next.js 14, Gemini AI, and Groq</p>
                    <p className="text-slate-500 text-xs mt-4">┬® 2026 AlgoMind Team. All rights reserved.</p>
                </CardContent>
            </Card>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useAuth } from '@/components/auth/AuthProvider';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Slider } from '@/components/ui/slider';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { toast } from 'sonner';
import { Mic, Play, Settings, Volume2 } from 'lucide-react';
import { getUserPreferences, saveUserPreferences } from '@/lib/supabase/user-preferences';

export function VoiceSettings() {
    const { user } = useAuth();
    const [voices, setVoices] = useState<SpeechSynthesisVoice[]>([]);
    const [selectedVoice, setSelectedVoice] = useState<string>('');
    const [rate, setRate] = useState<number>(1.1);
    const [isPlaying, setIsPlaying] = useState(false);
    const [loading, setLoading] = useState(true);

    // Load available voices
    useEffect(() => {
        const loadVoices = () => {
            if (typeof window !== 'undefined' && window.speechSynthesis) {
                const allVoices = window.speechSynthesis.getVoices();

                // Filter for US English, UK English, and Hindi (Indian English accent)
                // User Goal: 5+ options, mixed US, UK, and 1 Hindi accent
                const filtered = allVoices.filter(v =>
                    v.lang === 'en-US' ||
                    v.lang === 'en-GB' ||
                    v.lang === 'hi-IN'
                );

                // Deduplicate voices (remove similar ones like "Microsoft David Desktop" vs "Microsoft David")
                // Preference order: Google > Microsoft > System
                const uniqueVoices = filtered.filter((v, index, self) =>
                    index === self.findIndex((t) => (
                        t.name === v.name
                    ))
                ).sort((a, b) => {
                    // Sort order: US -> UK -> Hindi -> Others
                    const getOrder = (lang: string) => {
                        if (lang === 'en-US') return 1;
                        if (lang === 'en-GB') return 2;
                        if (lang === 'hi-IN') return 3;
                        return 4;
                    };
                    return getOrder(a.lang) - getOrder(b.lang);
                });

                // If we don't have enough (less than 5), add other English variants as backup
                if (uniqueVoices.length < 5) {
                    const others = allVoices.filter(v =>
                        v.lang.startsWith('en') &&
                        !uniqueVoices.some(uv => uv.name === v.name)
                    );
                    // Add distinct ones only
                    others.forEach(v => {
                        if (uniqueVoices.length < 8 && !uniqueVoices.some(uv => uv.name === v.name)) {
                            uniqueVoices.push(v);
                        }
                    });
                }

                setVoices(uniqueVoices);
            }
        };

        loadVoices();

        if (typeof window !== 'undefined' && window.speechSynthesis) {
            window.speechSynthesis.onvoiceschanged = loadVoices;
        }

        return () => {
            if (typeof window !== 'undefined' && window.speechSynthesis) {
                window.speechSynthesis.onvoiceschanged = null;
            }
        };
    }, []);

    // Load user preferences
    useEffect(() => {
        async function loadPrefs() {
            setLoading(true);
            try {
                const prefs = await getUserPreferences(user?.id || null);
                if (prefs.preferredVoiceName) {
                    setSelectedVoice(prefs.preferredVoiceName);
                } else {
                    // Default to first English voice if none selected
                    const defaultVoice = voices.find(v => v.name.includes("Google US English") || v.lang === 'en-US');
                    if (defaultVoice) setSelectedVoice(defaultVoice.name);
                }
                setRate(prefs.voiceRate || 1.0);
            } catch (e) {
                console.error("Failed to load voice preferences", e);
            } finally {
                setLoading(false);
            }
        }

        // Only load if voices are ready
        if (voices.length > 0) {
            loadPrefs();
        }
    }, [user, voices]);

    const handleSave = async () => {
        if (!selectedVoice) return;

        const voiceObj = voices.find(v => v.name === selectedVoice);

        try {
            await saveUserPreferences(user?.id || null, {
                preferredVoiceName: selectedVoice,
                preferredVoiceLang: voiceObj?.lang || 'en-US',
                voiceRate: rate
            });
            toast.success("Voice settings saved!");
        } catch (e) {
            toast.error("Failed to save settings.");
        }
    };

    const handleTestVoice = () => {
        if (!selectedVoice || typeof window === 'undefined') return;

        window.speechSynthesis.cancel();

        const voiceObj = voices.find(v => v.name === selectedVoice);
        if (!voiceObj) return;

        const utterance = new SpeechSynthesisUtterance("Hello! This is how I will sound during your interview practice. Good luck!");
        utterance.voice = voiceObj;
        utterance.rate = rate;
        utterance.onstart = () => setIsPlaying(true);
        utterance.onend = () => setIsPlaying(false);
        utterance.onerror = () => setIsPlaying(false);

        window.speechSynthesis.speak(utterance);
    };

    const handleRateChange = (vals: number[]) => {
        setRate(vals[0]);
    };

    if (loading && voices.length === 0) {
        return <div className="p-4 text-center text-slate-500">Loading voice engine...</div>;
    }

    return (
        <Card className="bg-slate-900/50 border-slate-800" data-tour="voice-capabilities">
            <CardHeader>
                <CardTitle className="text-white flex items-center gap-2">
                    <Volume2 className="w-5 h-5" />
                    Voice Capabilities
                </CardTitle>
                <CardDescription>Customize the AI interviewer's voice and speed</CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
                {/* Voice Selection */}
                <div className="space-y-3">
                    <label className="text-sm font-medium text-slate-300">AI Voice</label>
                    <Select value={selectedVoice} onValueChange={setSelectedVoice}>
                        <SelectTrigger className="w-full bg-slate-800/50 border-slate-700 text-white" disabled={voices.length === 0}>
                            <SelectValue placeholder={voices.length === 0 ? "Loading voices..." : "Select a voice"} />
                        </SelectTrigger>
                        <SelectContent className="max-h-[300px] bg-slate-900 border-slate-700 text-slate-200">
                            {voices.map((voice) => (
                                <SelectItem key={voice.name} value={voice.name} className="focus:bg-slate-800 focus:text-white cursor-pointer">
                                    <span className="flex items-center gap-2">
                                        {voice.name.replace(/Microsoft |Google /g, '')}
                                        <span className="text-xs text-slate-500 ml-1">({voice.lang})</span>
                                    </span>
                                </SelectItem>
                            ))}
                        </SelectContent>
                    </Select>
                </div>

                {/* Speed Slider */}
                <div className="space-y-4">
                    <div className="flex justify-between items-center">
                        <label className="text-sm font-medium text-slate-300">Speaking Rate</label>
                        <span className="text-xs font-mono text-blue-400 bg-blue-500/10 px-2 py-1 rounded">
                            {rate.toFixed(1)}x
                        </span>
                    </div>
                    <Slider
                        value={[rate]}
                        min={0.5}
                        max={2.0}
                        step={0.1}
                        onValueChange={handleRateChange}
                        className="py-4 [&_.bg-primary]:bg-indigo-600 [&_.bg-muted]:bg-indigo-600/20 [&_.border-input]:border-indigo-600/50"
                    />
                    <div className="flex justify-between text-[10px] text-slate-500 px-1">
                        <span>Slow</span>
                        <span>Normal</span>
                        <span>Fast</span>
                    </div>
                </div>

                {/* Actions */}
                <div className="flex gap-3 pt-2">
                    <Button
                        onClick={handleTestVoice}
                        variant="outline"
                        disabled={isPlaying}
                        className="flex-1 bg-slate-800/50 border-slate-700 hover:bg-slate-800 text-white"
                    >
                        {isPlaying ? (
                            <span className="animate-pulse">Speaking...</span>
                        ) : (
                            <>
                                <Play className="w-4 h-4 mr-2" />
                                Test Voice
                            </>
                        )}
                    </Button>
                    <Button
                        onClick={handleSave}
                        className="flex-1 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white font-bold"
                    >
                        Save Settings
                    </Button>
                </div>
            </CardContent>
        </Card>
    );
}

'use client';

import React, { useEffect, useState } from 'react';
import { TOUR_STEPS } from '@/lib/tour/steps';
import { useTour } from './TourContext';
import { AnimatePresence, motion } from 'framer-motion';
import { createPortal } from 'react-dom';
import { Button } from '@/components/ui/button';
import { X, ChevronRight, ChevronLeft, Sparkles } from 'lucide-react';
import { cn } from '@/lib/utils';
import { isMobileDevice } from '@/lib/utils/device-detection';

export function IntroTour() {
    const { isOpen, currentStep, nextStep, prevStep, skipTour, currentStepIndex } = useTour();
    const steps = TOUR_STEPS;
    const [targetRect, setTargetRect] = useState<DOMRect | null>(null);
    const [isMounted, setIsMounted] = useState(false);
    const [isMobile, setIsMobile] = useState(false);

    const updateTargetRect = React.useCallback(() => {
        if (!currentStep || currentStep.type === 'modal' || !currentStep.target) {
            setTargetRect(null);
            return;
        }

        // Try to find the element
        const el = document.querySelector(currentStep.target);
        if (el) {
            setTargetRect(el.getBoundingClientRect());
            // Ensure element is in view
            el.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'center' });
        } else {
            // Check if we should wait for it (retry handled by effect below)
            setTargetRect(null);
        }
    }, [currentStep]);

    useEffect(() => {
        setIsMounted(true);
        setIsMobile(isMobileDevice());

        const handleResize = () => {
            setIsMobile(isMobileDevice());
            updateTargetRect();
        };

        window.addEventListener('resize', handleResize);
        window.addEventListener('scroll', updateTargetRect, true);

        return () => {
            window.removeEventListener('resize', handleResize);
            window.removeEventListener('scroll', updateTargetRect, true);
        };
    }, [updateTargetRect]);

    // Smart Polling & Resize Logic
    useEffect(() => {
        if (!isOpen || !currentStep) return;

        let pollingInterval: NodeJS.Timeout;
        let stopPollingTimeout: NodeJS.Timeout;
        let resizeObserver: ResizeObserver;

        const cleanup = () => {
            clearInterval(pollingInterval);
            clearTimeout(stopPollingTimeout);
            if (resizeObserver) resizeObserver.disconnect();
        };

        let currentEl: Element | null = null;

        const checkTarget = () => {
            if (currentStep.type === 'modal' || !currentStep.target) {
                setTargetRect(null);
                currentEl = null;
                if (resizeObserver) resizeObserver.disconnect();
                return;
            }

            const el = document.querySelector(currentStep.target);

            // Case 1: Element found and is different from what we're tracking
            if (el && el !== currentEl) {
                currentEl = el;
                setTargetRect(el.getBoundingClientRect());
                el.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'center' });

                // Re-attach observer to new element
                if (resizeObserver) resizeObserver.disconnect();
                resizeObserver = new ResizeObserver(() => {
                    if (el.isConnected) {
                        setTargetRect(el.getBoundingClientRect());
                    }
                });
                resizeObserver.observe(el);
            }
            // Case 2: Element found and same as tracking -> Check if it moved/detached
            else if (el && el === currentEl) {
                if (!el.isConnected) {
                    // Detached! Reset.
                    currentEl = null;
                    setTargetRect(null);
                } else {
                    // Still there, update rect just in case (e.g. scroll/layout shift not caught by resize)
                    // Optional: only do this if really needed, ResizeObserver covers size. 
                    // Scroll listener covers scroll.
                    // But if it was hidden via display:none, rect might be 0.
                    const rect = el.getBoundingClientRect();
                    if (rect.width === 0 && rect.height === 0) {
                        setTargetRect(null);
                    } else {
                        setTargetRect(rect);
                    }
                }
            }
            // Case 3: Element not found
            else if (!el) {
                currentEl = null;
                setTargetRect(null);
                if (resizeObserver) resizeObserver.disconnect();
            }
        };

        // 1. Immediate check
        checkTarget();

        // 2. Continuous Poll (every 200ms) - WE DO NOT STOP POLLING
        // This ensures if the element is replaced (React re-render), we find the new one.
        pollingInterval = setInterval(checkTarget, 200);

        // 3. Safety Timeout (30s) - Only stop if step takes too long, to save memory
        stopPollingTimeout = setTimeout(() => {
            clearInterval(pollingInterval);
        }, 30000);

        return cleanup;
    }, [isOpen, currentStep]);

    // Keyboard navigation
    useEffect(() => {
        if (!isOpen) return;

        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                skipTour();
            }
            if (e.key === 'ArrowRight' || e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                nextStep();
            }
            if (e.key === 'ArrowLeft') {
                prevStep();
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isOpen, nextStep, prevStep, skipTour]);

    if (!isMounted || !isOpen || !currentStep) return null;

    // Portal for rendering outside normal flow
    const handleBackdropClick = (e: React.MouseEvent) => {
        if (isMobile) {
            e.stopPropagation();
            nextStep();
        }
    };

    // Portal for rendering outside normal flow
    const renderContent = () => {
        // --- 1. Modal Step (Welcome / Completion) ---
        if (currentStep.type === 'modal') {
            return (
                <AnimatePresence>
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-950/80 backdrop-blur-sm p-4"
                    >
                        <motion.div
                            initial={{ scale: 0.9, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            className="bg-slate-900 border border-slate-700 rounded-3xl p-6 max-w-md w-full shadow-2xl relative overflow-hidden"
                        >
                            <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-500 via-purple-500 to-pink-500" />

                            <div className="text-center space-y-6 pt-4">
                                <div className="w-20 h-20 mx-auto bg-slate-800 rounded-full flex items-center justify-center mb-4 relative">
                                    <div className="absolute inset-0 bg-blue-500/20 rounded-full animate-ping opacity-75" />
                                    <Sparkles className="w-10 h-10 text-blue-400" />
                                </div>

                                <div>
                                    <h2 className="text-2xl font-bold text-white mb-2">{currentStep.title}</h2>
                                    <div className="text-slate-400 text-base leading-relaxed whitespace-pre-line">
                                        {currentStep.content}
                                    </div>
                                </div>

                                <div className="flex flex-col gap-3 pt-4">
                                    <Button
                                        size="lg"
                                        onClick={nextStep}
                                        className="w-full bg-blue-600 hover:bg-blue-500 text-white font-bold h-12 rounded-xl shadow-lg shadow-blue-900/20"
                                    >
                                        {currentStepIndex === 0 ? "Start Tour" : "Finish"}
                                    </Button>
                                    <Button
                                        variant="ghost"
                                        onClick={skipTour}
                                        className="text-slate-500 hover:text-white"
                                    >
                                        {currentStepIndex === 0 ? "Skip for now" : "Close"}
                                    </Button>
                                </div>
                            </div>
                        </motion.div>
                    </motion.div>
                </AnimatePresence>
            );
        }

        // --- 2. Spotlight Step ---
        const hasTarget = !!targetRect;

        return (
            <div
                className={cn(
                    "fixed inset-0 z-[100]",
                    // On mobile, capture clicks everywhere (Tap to Next). 
                    // On desktop, passthrough events so user can interact IF target found.
                    isMobile ? "pointer-events-auto" : "pointer-events-none"
                )}
                onClick={handleBackdropClick}
            >
                {/* Spotlight Overlay via Box-Shadow */}
                {hasTarget ? (
                    <div
                        className={cn(
                            "absolute transition-all duration-300 ease-in-out pointer-events-none",
                            currentStep.spotlightShape === 'circle' ? "rounded-full" : "rounded-xl",
                            "border-[3px] border-indigo-500 shadow-[0_0_20px_rgba(99,102,241,0.5)]"
                        )}
                        style={{
                            top: targetRect!.top - 8,
                            left: targetRect!.left - 8,
                            width: targetRect!.width + 16,
                            height: targetRect!.height + 16,
                            // The Box Shadow Trick: Creates the dark overlay with a cutout
                            boxShadow: `0 0 0 9999px ${isMobile ? 'rgba(0,0,0,0.80)' : 'rgba(0,0,0,0.75)'}`,
                        }}
                    />
                ) : (
                    // Fallback full overlay if target not found yet
                    // Make this pointer-events-auto always to block page interaction when target missing
                    <div className="absolute inset-0 bg-slate-950/80 pointer-events-auto" />
                )}

                {/* Tooltip */}
                <AnimatePresence mode="wait">
                    <motion.div
                        key={currentStep.id}
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -10 }}
                        transition={{ duration: 0.3 }}
                        onClick={(e) => e.stopPropagation()} // Prevent tap-to-next when clicking tooltip itself
                        className={cn(
                            "pointer-events-auto absolute",
                            isMobile
                                ? cn(
                                    "left-0 right-0 p-4",
                                    // Default to bottom sheet, but allow override to top
                                    currentStep.mobilePosition === 'top'
                                        ? "top-20 rounded-b-3xl border-t-0 shadow-xl"
                                        : "bottom-0 rounded-t-3xl border-b-0"
                                )
                                : "max-w-xs" // Desktop
                        )}
                        style={!isMobile && hasTarget ? {
                            // Desktop Positioning with Clamping to prevent overflow
                            top: Math.max(10, Math.min(window.innerHeight - 300,
                                currentStep.position === 'top' ? targetRect!.top - 200 :
                                    currentStep.position === 'bottom' ? targetRect!.bottom + 20 :
                                        targetRect!.top
                            )),
                            left: Math.max(10, Math.min(window.innerWidth - 350,
                                currentStep.position === 'left' ? targetRect!.left - 340 :
                                    currentStep.position === 'right' ? targetRect!.right + 20 :
                                        targetRect!.left + (targetRect!.width / 2) - 160
                            )),
                        } : isMobile ? undefined : {
                            // Centered Desktop Fallback if target missing
                            top: '50%',
                            left: '50%',
                            transform: 'translate(-50%, -50%)'
                        }}
                    >
                        <div className={cn(
                            "bg-slate-900 border border-slate-700 shadow-2xl overflow-hidden",
                            isMobile
                                ? cn(
                                    currentStep.mobilePosition === 'top' ? "rounded-b-2xl border-t-0" : "rounded-t-3xl border-b-0 pb-8"
                                )
                                : "rounded-2xl"
                        )}>
                            {isMobile && currentStep.mobilePosition !== 'top' && (
                                <div className="w-full flex justify-center pt-3 pb-1">
                                    <div className="w-12 h-1.5 bg-slate-700 rounded-full" />
                                </div>
                            )}

                            <div className="p-5">
                                <div className="flex justify-between items-start mb-3">
                                    <h3 className="font-bold text-white text-lg">{currentStep.title}</h3>
                                    <button onClick={skipTour} className="text-slate-500 hover:text-white p-1">
                                        <X className="w-5 h-5" />
                                    </button>
                                </div>

                                <p className="text-slate-300 text-sm leading-relaxed mb-6">
                                    {currentStep.content}
                                </p>

                                <div className="flex items-center justify-between gap-4">
                                    <span className="text-xs font-medium text-slate-500">
                                        Step {currentStepIndex + 1} of {steps.length}
                                    </span>
                                    <div className="flex gap-2">
                                        {currentStepIndex > 0 && (
                                            <Button
                                                size="sm"
                                                variant="outline"
                                                onClick={prevStep}
                                                className="h-9 px-3 border-slate-700 text-slate-300"
                                            >
                                                <ChevronLeft className="w-4 h-4" />
                                            </Button>
                                        )}
                                        <Button
                                            size="sm"
                                            onClick={nextStep}
                                            className="h-9 px-4 bg-blue-600 hover:bg-blue-500 text-white font-bold shadow-lg shadow-blue-900/20"
                                        >
                                            {currentStepIndex === steps.length - 1 ? "Finish" : "Next"}
                                            {currentStepIndex !== steps.length - 1 && <ChevronRight className="w-4 h-4 ml-1" />}
                                        </Button>
                                    </div>
                                </div>
                            </div>
                            <div className="h-1 w-full bg-gradient-to-r from-blue-600 via-purple-600 to-indigo-600" />
                        </div>
                    </motion.div>
                </AnimatePresence>
            </div >
        );
    };

    return createPortal(renderContent(), document.body);
}

'use client';

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { usePathname, useRouter, useSearchParams } from 'next/navigation';
import { TOUR_STEPS, TourStep } from '@/lib/tour/steps';
import { useAuth } from '@/components/auth/AuthProvider';
import { enableDemoMode, disableDemoMode, isDemoMode } from '@/lib/demo/manager';

interface TourContextType {
    isOpen: boolean;
    currentStepIndex: number;
    currentStep: TourStep | null;
    nextStep: () => void;
    prevStep: () => void;
    skipTour: () => void;
    startTour: () => void;
    isFirstVisit: boolean;
}

const TourContext = createContext<TourContextType | undefined>(undefined);

export function TourProvider({ children }: { children: React.ReactNode }) {
    const [isOpen, setIsOpen] = useState(false);
    const [currentStepIndex, setCurrentStepIndex] = useState(0);
    const [isFirstVisit, setIsFirstVisit] = useState(false);
    const { user, loading } = useAuth();
    const router = useRouter();
    const pathname = usePathname();
    // const searchParams = useSearchParams(); // Not used directly in logic yet, but good to have if needed

    const executeAction = useCallback(async (action: TourStep['action']) => {
        if (typeof action === 'function') {
            try {
                await action({ router });
            } catch (error) {
                console.error('Tour action failed:', error);
            }
        }
    }, [router]);

    const getNextValidStepIndex = useCallback((currentIndex: number, direction: 'next' | 'prev'): number => {
        let nextIndex = direction === 'next' ? currentIndex + 1 : currentIndex - 1;

        // Loop until we find a valid step or hit the bounds
        while (nextIndex >= 0 && nextIndex < TOUR_STEPS.length) {
            const step = TOUR_STEPS[nextIndex];
            if (!step.shouldShow || step.shouldShow(user)) {
                return nextIndex;
            }
            nextIndex = direction === 'next' ? nextIndex + 1 : nextIndex - 1;
        }

        return nextIndex; // Return out of bounds index (stops tour)
    }, [user]);

    const handleStepChange = useCallback(async (index: number) => {
        const step = TOUR_STEPS[index];
        if (!step) {
            setIsOpen(false);
            return;
        }

        // Execute pre-action if any (e.g. navigate before showing step)
        if (step.action) {
            await executeAction(step.action);
        }

        setCurrentStepIndex(index);
    }, [executeAction]);

    const nextStep = useCallback(() => {
        const nextIndex = getNextValidStepIndex(currentStepIndex, 'next');
        if (nextIndex < TOUR_STEPS.length) {
            handleStepChange(nextIndex);
        } else {
            // End of tour
            localStorage.setItem('algomind_tour_completed', 'true');

            // Auto-disable Demo Mode
            disableDemoMode();
            window.dispatchEvent(new CustomEvent('demo-mode-changed', { detail: { enabled: false } }));

            setIsOpen(false);
        }
    }, [currentStepIndex, handleStepChange, getNextValidStepIndex]);

    const prevStep = useCallback(() => {
        const prevIndex = getNextValidStepIndex(currentStepIndex, 'prev');
        if (prevIndex >= 0) {
            handleStepChange(prevIndex);
        }
    }, [currentStepIndex, handleStepChange, getNextValidStepIndex]);

    const skipTour = useCallback(() => {
        localStorage.setItem('algomind_tour_skipped', 'true');

        // Auto-disable Demo Mode on skip too
        disableDemoMode();
        window.dispatchEvent(new CustomEvent('demo-mode-changed', { detail: { enabled: false } }));

        setIsOpen(false);
    }, []);

    const startTour = useCallback(() => {
        // Auto-enable Demo Mode
        enableDemoMode();
        window.dispatchEvent(new CustomEvent('demo-mode-changed', { detail: { enabled: true } }));

        setIsOpen(true);
        // Find first valid step
        let firstIndex = 0;
        while (firstIndex < TOUR_STEPS.length) {
            const step = TOUR_STEPS[firstIndex];
            if (!step.shouldShow || step.shouldShow(user)) break;
            firstIndex++;
        }
        handleStepChange(firstIndex);
    }, [handleStepChange, user]);

    // 3. Auto-Start for New Users (Hardened Logic)
    // Moved here to avoid use-before-declaration error
    const tourScheduledRef = React.useRef(false);

    useEffect(() => {
        if (loading) return;

        // CRITICAL: Force disable Demo/Tour if not logged in
        if (!user) {
            if (isDemoMode()) {
                disableDemoMode();
                window.dispatchEvent(new CustomEvent('demo-mode-changed', { detail: { enabled: false } }));
            }
            setIsOpen(false);
            tourScheduledRef.current = false; // Reset if user logs out
            return;
        }

        // 1. Resume Tour if Demo Mode is active (Persistence)
        if (isDemoMode()) {
            setIsOpen(true);
            return;
        }

        const hasCompletedTour = localStorage.getItem('algomind_tour_completed');
        const hasSkippedTour = localStorage.getItem('algomind_tour_skipped');
        const isNewUser = !hasCompletedTour && !hasSkippedTour;

        // 2. Auto-Start for New Users
        // We use a ref to ensure we only schedule this ONCE per session/mount
        if (isNewUser && user && !tourScheduledRef.current) {
            tourScheduledRef.current = true;
            setIsFirstVisit(true);

            console.log('­ƒåò [TOUR] New user detected, scheduling tour start...');

            // Delay auto-start slightly for better UX and to ensure UI is ready
            // We do NOT return the cleanup function to clear this timeout
            // because we want it to persist even if the component re-renders 
            // (unless the user explicitly logs out, handled above)
            setTimeout(() => {
                // Check if still valid to start (e.g. didn't log out in the last 2 seconds)
                // We re-check localStorage in case they finished it in another tab (unlikely but safe)
                const currentCompleted = localStorage.getItem('algomind_tour_completed');
                const currentSkipped = localStorage.getItem('algomind_tour_skipped');

                if (!currentCompleted && !currentSkipped && !isDemoMode()) {
                    console.log('­ƒÜÇ [TOUR] Starting auto-tour now');
                    startTour();
                }
            }, 1500);
        }
    }, [loading, user, startTour]);

    // Listen for custom start event (from settings)
    useEffect(() => {
        const handleStart = () => startTour();
        window.addEventListener('start-tour', handleStart);
        return () => window.removeEventListener('start-tour', handleStart);
    }, [startTour]);

    // Current step specific logic
    const currentStep = TOUR_STEPS[currentStepIndex];

    return (
        <TourContext.Provider value={{
            isOpen,
            currentStepIndex,
            currentStep,
            nextStep,
            prevStep,
            skipTour,
            startTour,
            isFirstVisit
        }}>
            {children}
        </TourContext.Provider>
    );
}

export function useTour() {
    const context = useContext(TourContext);
    if (context === undefined) {
        throw new Error('useTour must be used within a TourProvider');
    }
    return context;
}

'use client';

import { TourStep } from '@/lib/tour/steps';
import { Button } from '@/components/ui/button';
import { motion, AnimatePresence } from 'framer-motion';
import { X, ChevronRight, ChevronLeft } from 'lucide-react';
import { cn } from '@/lib/utils';
import { isDemoMode } from '@/lib/demo/manager';

interface TourTooltipProps {
    step: TourStep;
    currentStepIndex: number;
    totalSteps: number;
    onNext: () => void;
    onPrev: () => void;
    onSkip: () => void;
    position: { top: number; left: number; placement: 'top' | 'bottom' | 'left' | 'right' | 'center' };
}

export function TourTooltip({
    step,
    currentStepIndex,
    totalSteps,
    onNext,
    onPrev,
    onSkip,
    position
}: TourTooltipProps) {
    const isLastStep = currentStepIndex === totalSteps - 1;
    const isDemo = isDemoMode();

    return (
        <motion.div
            initial={{ opacity: 0, scale: 0.9, y: 10 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.9 }}
            transition={{ type: 'spring', damping: 25, stiffness: 300 }}
            className="fixed z-[10002] bg-slate-900/95 backdrop-blur-md border border-slate-700 rounded-xl shadow-[0_10px_40px_rgba(0,0,0,0.5)] p-6 max-w-[90vw] w-[400px]"
            style={{
                top: position.top,
                left: position.left,
            }}
        >
            {/* Skip Button */}
            <button
                onClick={onSkip}
                className="absolute top-4 right-4 text-red-400 hover:text-red-300 text-xs font-bold uppercase tracking-wider transition-colors"
                aria-label="Skip Tour"
            >
                Skip Tour
            </button>

            {/* Content */}
            <div className="space-y-4 pt-2">
                <div>
                    <h3 className="text-lg font-bold text-white mb-2 pr-16">{step.title}</h3>
                    <div className="text-slate-300 text-sm leading-relaxed whitespace-pre-line">
                        {step.content}
                    </div>
                </div>

                {/* Progress Bar */}
                <div className="w-full h-1 bg-slate-800 rounded-full overflow-hidden">
                    <motion.div
                        className="h-full bg-blue-500"
                        initial={{ width: 0 }}
                        animate={{ width: `${((currentStepIndex + 1) / totalSteps) * 100}%` }}
                    />
                </div>

                {/* Footer Controls */}
                <div className="flex items-center justify-between pt-2">
                    <span className="text-xs font-semibold text-slate-500">
                        Step {currentStepIndex + 1} of {totalSteps}
                    </span>

                    <div className="flex gap-2">
                        {currentStepIndex > 0 && (
                            <Button
                                onClick={onPrev}
                                variant="outline"
                                size="sm"
                                className="border-slate-700 hover:bg-slate-800 text-slate-300"
                            >
                                <ChevronLeft className="w-4 h-4 mr-1" />
                                Back
                            </Button>
                        )}
                        <Button
                            onClick={onNext}
                            size="sm"
                            className={cn(
                                "font-bold shadow-lg shadow-blue-900/20",
                                isLastStep
                                    ? "bg-emerald-600 hover:bg-emerald-500 text-white"
                                    : "bg-indigo-600 hover:bg-indigo-500 text-white"
                            )}
                        >
                            {isLastStep ? "Finish" : "Next"}
                            {!isLastStep && <ChevronRight className="w-4 h-4 ml-1" />}
                        </Button>
                    </div>
                </div>
            </div>

            {/* Arrow/Pointer (Optional visual flair) */}
            {/* We can calculate arrow position based on placement prop if needed, 
                but for now slight offset handling in IntroTour is enough */}
        </motion.div>
    );
}

import React from 'react';
import { Mic, MicOff, Loader2, AlertCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import { Badge } from '@/components/ui/badge';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';

interface MicrophoneButtonProps {
    isListening: boolean;
    onClick: () => void;
    disabled?: boolean;
    className?: string;
    error?: string | null;
}

export function MicrophoneButton({
    isListening,
    onClick,
    disabled = false,
    className,
    error
}: MicrophoneButtonProps) {

    // Visual states: idle (gray), listening (pulsing blue), processing (spinning - implicitly handled by parent logic usually, but here mapped to listening for now)

    return (
        <div className="flex flex-col items-center gap-2">
            <TooltipProvider>
                <Tooltip>
                    <TooltipTrigger asChild>
                        <Button
                            variant={isListening ? "default" : "outline"}
                            size="icon"
                            data-testid="mic-button"
                            className={cn(
                                "h-16 w-16 rounded-full transition-all duration-200 shadow-lg relative",
                                isListening
                                    ? "bg-blue-600 hover:bg-blue-700 border-blue-500 ring-2 ring-blue-500/20"
                                    : "bg-white hover:bg-slate-200 text-slate-900 border-white ring-2 ring-white/20",
                                error ? "border-red-500 text-red-500" : "",
                                className
                            )}
                            onClick={onClick}
                            disabled={disabled}
                        >
                            {isListening ? (
                                <Mic className="h-8 w-8 text-white" />
                            ) : (
                                <MicOff className={cn("h-8 w-8", error ? "text-red-500" : "text-slate-900")} />
                            )}
                        </Button>
                    </TooltipTrigger>
                    <TooltipContent>
                        {error ? error : isListening ? "Stop Listening" : "Start Speaking"}
                    </TooltipContent>
                </Tooltip>
            </TooltipProvider>

            {/* State Label */}
            <Badge variant={isListening ? "default" : "secondary"} className={cn(isListening ? "bg-blue-100 text-blue-800 hover:bg-blue-200" : "")}>
                {isListening ? "Listening..." : "Click to Speak"}
            </Badge>
        </div>
    );
}

import React, { useEffect, useRef } from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { cn } from '@/lib/utils';
import { Edit2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';

interface TranscriptViewerProps {
    transcript: string;
    interimTranscript: string;
    onEdit?: (newTranscript: string) => void;
    isEditable?: boolean;
}

export function TranscriptViewer({
    transcript,
    interimTranscript,
    onEdit,
    isEditable = true
}: TranscriptViewerProps) {
    const scrollRef = useRef<HTMLDivElement>(null);
    const [isEditing, setIsEditing] = React.useState(false);
    const [editedText, setEditedText] = React.useState(transcript);

    // Auto-scroll to bottom when text changes
    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [transcript, interimTranscript]);

    useEffect(() => {
        setEditedText(transcript);
    }, [transcript]);

    const handleSave = () => {
        if (onEdit) {
            onEdit(editedText);
        }
        setIsEditing(false);
    };

    return (
        <Card className="w-full h-full border-none bg-transparent shadow-none">
            <CardContent className="p-3 h-full flex flex-col relative group">
                {!isEditing && isEditable && transcript.length > 0 && (
                    <Button
                        variant="ghost"
                        size="icon"
                        className="absolute top-1 right-1 h-6 w-6 opacity-0 group-hover:opacity-100 transition-opacity z-10"
                        onClick={() => setIsEditing(true)}
                    >
                        <Edit2 className="h-3 w-3 text-muted-foreground" />
                    </Button>
                )}

                {isEditing ? (
                    <div className="flex flex-col h-full gap-2">
                        <Textarea
                            value={editedText}
                            onChange={(e) => setEditedText(e.target.value)}
                            className="flex-1 resize-none p-2 text-xs font-medium bg-slate-900/50 border-slate-800"
                            placeholder="Edit your transcript..."
                        />
                        <div className="flex justify-end gap-2">
                            <Button variant="outline" size="xs" className="h-6 text-[10px]" onClick={() => setIsEditing(false)}>Cancel</Button>
                            <Button size="xs" className="h-6 text-[10px]" onClick={handleSave}>Save</Button>
                        </div>
                    </div>
                ) : (
                    <div
                        ref={scrollRef}
                        className="h-full overflow-y-auto pr-2 space-y-1 font-medium text-[11px] leading-relaxed scrollbar-thin scrollbar-thumb-slate-800"
                    >
                        {transcript ? (
                            <span className="text-slate-200">{transcript}</span>
                        ) : (
                            <span className="text-slate-500 italic">Start speaking to see transcript...</span>
                        )}

                        {interimTranscript && (
                            <span className="text-slate-500 italic ml-1">{interimTranscript}</span>
                        )}
                    </div>
                )}
            </CardContent>
        </Card>
    );
}

