        (React.useState as Mock)
            .mockReturnValueOnce([false, mockSetIsListening])
            .mockReturnValueOnce([false, mockSetIsSpeaking])
            .mockReturnValueOnce([null, mockSetError])
            .mockReturnValueOnce([false, mockSetIsInitializing])
