// ÔöÇÔöÇ Helpers ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

/** Create a fake async iterable from an array of token strings. */
async function* fakeStream(tokens: string[]): AsyncGenerator<string> {
    for (const token of tokens) {
        yield token;
    }
}

/** Collect all chunks from an async generator into an array. */
async function collectChunks(
    gen: AsyncGenerator<ResponseChunk>
): Promise<ResponseChunk[]> {
    const chunks: ResponseChunk[] = [];
    for await (const chunk of gen) {
        chunks.push(chunk);
    }
    return chunks;
}

// ÔöÇÔöÇ isSentenceBoundary ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

describe('isSentenceBoundary', () => {
    test('period at end of sentence ÔåÆ true', () => {
        expect(isSentenceBoundary('Hello world.')).toBe(true);
    });

    test('exclamation mark ÔåÆ true', () => {
        expect(isSentenceBoundary('Hello world!')).toBe(true);
    });

    test('question mark ÔåÆ true', () => {
        expect(isSentenceBoundary('Is this correct?')).toBe(true);
    });

    test('no punctuation ÔåÆ false', () => {
        expect(isSentenceBoundary('Hello world')).toBe(false);
    });

    test('abbreviation "Dr." ÔåÆ false', () => {
        expect(isSentenceBoundary('Talk to Dr.')).toBe(false);
    });

    test('abbreviation "Mr." ÔåÆ false', () => {
        expect(isSentenceBoundary('Hello Mr.')).toBe(false);
    });

    test('abbreviation "vs." ÔåÆ false', () => {
        expect(isSentenceBoundary('arrays vs.')).toBe(false);
    });

    test('abbreviation "etc." ÔåÆ false', () => {
        expect(isSentenceBoundary('apples, oranges, etc.')).toBe(false);
    });

    test('abbreviation "e.g." ÔåÆ false', () => {
        expect(isSentenceBoundary('for example e.g.')).toBe(false);
    });

    test('single letter abbreviation "U." ÔåÆ false', () => {
        expect(isSentenceBoundary('The U.')).toBe(false);
    });

    test('acronym pattern "U.S.A." ÔåÆ false', () => {
        expect(isSentenceBoundary('In the U.S.A.')).toBe(false);
    });

    test('decimal number "3.14" ÔåÆ false', () => {
        expect(isSentenceBoundary('Pi is 3.14')).toBe(false);
    });

    test('empty string ÔåÆ false', () => {
        expect(isSentenceBoundary('')).toBe(false);
    });
});

// ÔöÇÔöÇ countWords ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ

describe('countWords', () => {
