export class APIError extends Error {
    constructor(
        message: string,
        public statusCode?: number,
        public retryable: boolean = false
    ) {
        super(message);
        this.name = 'APIError';
    }
}

export async function handleAPIError(error: unknown): Promise<never> {
    if (error instanceof APIError) {
        throw error;
    }

    if (error instanceof Error) {
        const message = error.message.toLowerCase();

        if (message.includes('rate') || message.includes('limit') || message.includes('quota')) {
            throw new APIError('Rate limit exceeded. Please try again in a moment.', 429, true);
        }

        if (message.includes('network') || message.includes('fetch')) {
            throw new APIError('Network error. Please check your connection.', 0, true);
        }

        if (message.includes('timeout')) {
            throw new APIError('Request timed out. Please try again.', 408, true);
        }

        if (message.includes('unauthorized') || message.includes('401')) {
            throw new APIError('Authentication failed. Please refresh the page.', 401, false);
        }
    }

    throw new APIError('An unexpected error occurred. Please try again.', 500, true);
}

export async function retryWithBackoff<T>(
    fn: () => Promise<T>,
    maxRetries: number = 3,
    baseDelayMs: number = 1000
): Promise<T> {
    let lastError: Error = new Error('No attempts made');

    for (let attempt = 0; attempt < maxRetries; attempt++) {
        try {
            return await fn();
        } catch (error: unknown) {
            lastError = error instanceof Error ? error : new Error(String(error));

            // Don't retry non-retryable errors
            if (error instanceof APIError && !error.retryable) {
                throw error;
            }

            if (attempt < maxRetries - 1) {
                // Exponential backoff with jitter
                const delay = Math.min(baseDelayMs * Math.pow(2, attempt), 10000);
                const jitter = Math.random() * 500;
                await new Promise(resolve => setTimeout(resolve, delay + jitter));
            }
        }
    }

    throw lastError;
}

/**
 * Wrap an async function with automatic error handling
 */
export function withErrorHandling<T extends (...args: any[]) => Promise<any>>(
    fn: T,
    onError?: (error: Error) => void
): T {
    return (async (...args: Parameters<T>) => {
        try {
            return await fn(...args);
        } catch (error: unknown) {
            const handledError = error instanceof Error ? error : new Error(String(error));
            onError?.(handledError);
            throw handledError;
        }
    }) as T;
}

/**
 * Check if an error is transient and should be retried
 */
export function isTransientError(error: unknown): boolean {
    if (error instanceof APIError) {
        return error.retryable;
    }

    if (error instanceof Error) {
        const message = error.message.toLowerCase();
        return (
            message.includes('network') ||
            message.includes('timeout') ||
            message.includes('rate') ||
            message.includes('503') ||
            message.includes('502') ||
            message.includes('504')
        );
    }

    return false;
}

/**
 * Interruption context builder.
 *
 * When the user interrupts the AI mid-response, this utility builds a
 * concise prompt fragment that can be injected into the next AI turn so
 * the model is aware of what it was saying before being cut off.
 *
 * @module interruption-context
 */

/** Maximum characters of partial content to include in the prompt. */
const MAX_PARTIAL_LENGTH = 150;

/**
 * Build a context fragment describing an interrupted AI response.
 *
 * @param partialResponse - The text the AI had spoken before interruption.
 * @param interruptedAt   - Unix timestamp of the interruption.
 * @returns A short prompt fragment, or empty string if input is empty.
 */
export function buildInterruptionContext(
    partialResponse: string,
    interruptedAt: number,
): string {
    if (!partialResponse || partialResponse.trim().length === 0) {
        return '';
    }

    // Truncate to avoid bloating the prompt
    const truncated =
        partialResponse.length > MAX_PARTIAL_LENGTH
            ? partialResponse.slice(0, MAX_PARTIAL_LENGTH).trimEnd() + 'ÔÇª'
            : partialResponse;

    return (
        `[INTERRUPTION CONTEXT] You were explaining: "${truncated}" ` +
        `but the user interrupted you. Briefly acknowledge what you were saying ` +
        `and address their new input. Do not repeat your previous explanation in full.`
    );
}

/**
 * Extract the portion of an AI response that was actually spoken (heard)
 * before the user interrupted.
 *
 * Since TTS processes text in sentence-level chunks, we estimate the
 * spoken portion by counting how many chunks could have been spoken
 * given the elapsed time since speech started.
 *
 * @param fullResponse   - The full AI response text.
 * @param speechStartMs  - Unix timestamp when speech began.
 * @param interruptionMs - Unix timestamp when interruption occurred.
 * @param avgChunkMs     - Average time to speak one chunk (default 3000ms).
 * @returns The estimated partial content that was heard.
 */
export function estimateSpokenContent(
    fullResponse: string,
    speechStartMs: number,
    interruptionMs: number,
    avgChunkMs = 3000,
): string {
    if (!fullResponse) return '';

    const elapsed = Math.max(0, interruptionMs - speechStartMs);
    const estimatedChunks = Math.max(1, Math.ceil(elapsed / avgChunkMs));

    // Split into sentences (rough approximation)
    const sentences = fullResponse.match(/[^.!?]+[.!?]+/g) || [fullResponse];
    const spokenSentences = sentences.slice(0, estimatedChunks);

    return spokenSentences.join('').trim();
}

export type InterviewState =
    | 'idle'
    | 'problem-intro'      // AI introduces problem
    | 'user-thinking'      // User explains approach
    | 'ai-clarifying'      // AI asks questions
    | 'user-solving'       // User walks through solution
    | 'ai-feedback'        // AI provides hints/feedback
    | 'solution-review'    // Final discussion
    | 'assessment'         // AI generates cognitive report
    | 'completed';

export type InterviewEvent =
    | 'START'
    | 'USER_FINISHED_SPEAKING'
    | 'AI_FINISHED_SPEAKING'
    | 'MOVE_TO_SOLVING'
    | 'REQUEST_HINT'
    | 'SUBMIT_SOLUTION'
    | 'FINISH_INTERVIEW';

export class InterviewStateMachine {
    private state: InterviewState = 'idle';

    getState(): InterviewState {
        return this.state;
    }

    transition(event: InterviewEvent): InterviewState {
        const previous = this.state;

        switch (this.state) {
            case 'idle':
                if (event === 'START') this.state = 'problem-intro';
                break;

            case 'problem-intro':
                if (event === 'AI_FINISHED_SPEAKING') this.state = 'user-thinking';
                break;

            case 'user-thinking':
                if (event === 'USER_FINISHED_SPEAKING') this.state = 'ai-clarifying';
                if (event === 'MOVE_TO_SOLVING') this.state = 'user-solving';
                break;

            case 'ai-clarifying':
                if (event === 'AI_FINISHED_SPEAKING') this.state = 'user-thinking'; // Loop back for more discussion
                if (event === 'MOVE_TO_SOLVING') this.state = 'user-solving';
                break;

            case 'user-solving':
                if (event === 'USER_FINISHED_SPEAKING') this.state = 'ai-feedback';
                if (event === 'SUBMIT_SOLUTION') this.state = 'solution-review';
                break;

            case 'ai-feedback':
                if (event === 'AI_FINISHED_SPEAKING') this.state = 'user-solving'; // Back to solving
                break;

            case 'solution-review':
                if (event === 'FINISH_INTERVIEW') this.state = 'assessment';
                break;

            case 'assessment':
                if (event === 'AI_FINISHED_SPEAKING') this.state = 'completed';
                break;
        }

        return this.state;
    }

    reset() {
        this.state = 'idle';
    }
}

import { getSupabase, isSupabaseConfigured } from '@/lib/supabase/client';
import { SupabaseClient } from '@supabase/supabase-js';
import { logSystemEvent } from '@/lib/monitoring/events';

const DAILY_LIMIT = 5;
const LOCAL_STORAGE_KEY = 'algomind_daily_usage';

export interface RateLimitResult {
    allowed: boolean;
    remaining: number;
    isAdmin: boolean;
}

interface LocalUsage {
    date: string;
    count: number;
}

/**
 * Check if user has remaining questions for today
 * Admins are exempt from limits
 */
export async function checkUserRateLimit(userId: string | null): Promise<RateLimitResult> {
    // Guest users have no rate limit (they have trial limit instead)
    if (!userId || userId === 'guest-user') {
        return { allowed: true, remaining: 999, isAdmin: false };
    }

    const supabase = getSupabase();

    // If Supabase not configured, use localStorage
    if (!supabase || !isSupabaseConfigured()) {
        return checkLocalRateLimit();
    }

    try {
        // Use the database function
        const { data, error } = await supabase.rpc('check_user_rate_limit', {
            p_user_id: userId,
            p_limit: DAILY_LIMIT
        });

        if (error) {
            console.error('ÔØî [Rate Limit] Check failed:', error);
            // Fail OPEN - allow on error so missing RPCs or DB issues don't block users
            return { allowed: true, remaining: DAILY_LIMIT, isAdmin: false };
        }

        const result = data?.[0];
        if (!result) {
            // No data returned - fail open
            return { allowed: true, remaining: DAILY_LIMIT, isAdmin: false };
        }

        if (!result.allowed && !result.is_admin_user) {
            void logSystemEvent({
                type: 'user_rate_limit',
                userId: userId,
                metadata: { count: DAILY_LIMIT - result.remaining, limit: DAILY_LIMIT }
            });
        }

        return {
            allowed: result.allowed,
            remaining: result.remaining,
            isAdmin: result.is_admin_user
        };
    } catch (error: unknown) {
        console.error('ÔØî [Rate Limit] Unexpected error:', error);
        // Fail open - don't block users on unexpected errors
        return { allowed: true, remaining: DAILY_LIMIT, isAdmin: false };
    }
}


/**
 * Increment user usage count in DB
 */
export async function incrementUserUsage(userId: string, supabaseClient?: SupabaseClient): Promise<void> {
    if (!userId || userId === 'guest-user') {
        recordLocalQuestion();
        return;
    }

    const supabase = supabaseClient || getSupabase();

    if (!supabase) {
        console.warn('ÔÜá´©Å [Rate Limit] No Supabase client available to increment usage');
        return;
    }

    try {
        const today = new Date().toISOString().split('T')[0];

        // We use upsert to simplify the logic: 
        // if row exists, we want to increment. 
        // BUT standard REST upsert overrides the row. 
        // So safest is to use RPC if available, or just insert and handle conflict if we don't have an atomic increment RPC.
        // Given constraints, we will rely on strict rate limit checking which calls RPC.
        // Use a simple upsert for now designed to just "ensure" a record exists, 
        // but for accurate incrementing we should probably use an RPC or careful logic.
        // Actually, the requirement says: "increment questions_used by 1 for today, or insert a new row with questions_used = 1"
        // Let's use the `record_user_question` RPC if it exists (it was called in the original code! line 79)
        // RPC: check_user_rate_limit was mentioned. 
        // Wait, the original code had: await supabase.rpc('record_user_question', { p_user_id: userId });
        // I should USE that if it works. 

        const { error } = await supabase.rpc('record_user_question', {
            p_user_id: userId
        });

        if (error) {
            console.error('ÔØî [Rate Limit] Failed to record usage via RPC:', error);
        }

    } catch (error: unknown) {
        console.error('ÔØî [Rate Limit] Error recording usage:', error);
    }
}

/**
 * LocalStorage fallback for when Supabase isn't configured
 */
function checkLocalRateLimit(): RateLimitResult {
    try {
        const today = new Date().toISOString().split('T')[0];
        const stored = localStorage.getItem(LOCAL_STORAGE_KEY);

        if (!stored) {
            return { allowed: true, remaining: DAILY_LIMIT, isAdmin: false };
        }

        const usage: LocalUsage = JSON.parse(stored);

        // Reset if different day
        if (usage.date !== today) {
            return { allowed: true, remaining: DAILY_LIMIT, isAdmin: false };
        }

        const remaining = Math.max(0, DAILY_LIMIT - usage.count);

        if (remaining === 0) {
            void logSystemEvent({
                type: 'user_rate_limit',
                userId: 'local',
                metadata: { count: usage.count, limit: DAILY_LIMIT }
            });
        }

        return {
            allowed: remaining > 0,
            remaining,
            isAdmin: false
        };
    } catch {
        return { allowed: true, remaining: DAILY_LIMIT, isAdmin: false };
    }
}

function recordLocalQuestion(): void {
    try {
        const today = new Date().toISOString().split('T')[0];
        const stored = localStorage.getItem(LOCAL_STORAGE_KEY);

        const usage: LocalUsage = { date: today, count: 1 };

        if (stored) {
            const existing: LocalUsage = JSON.parse(stored);
            if (existing.date === today) {
                usage.count = existing.count + 1;
            }
        }

        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(usage));
    } catch {
        // Ignore storage errors
    }
}

